L29_1.m_Pos = "L"
L29_1.m_Talk_KOREA = "혼자 있는 사람을 갑자기 뒤에서 끌어안으면 놀라는 게 당연하다고 생각하는데......"
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = "一人でいるところを後ろから抱きつかれたら、ビックリするに決まってるでしょ……"
L29_1.m_Talk_ENG = "Wouldn't you be caught off guard if someone randomly hugged you from behind...?"
L29_1.m_Talk_TWN = "被人突然從背後抱住，會被嚇到是當然的吧……"
L29_1.m_Talk_THA = "จู่ๆ มีใครก็ไม่รู้มากอดจากด้านหลัง เป็นใครก็ต้องตกใจอยู่แล้วไม่ใช่เรอะ..."
L29_1.m_Talk_VTN = "Cậu không giật mình nếu bị người khác ôm từ phía sau à...?"
L29_1.m_Talk_SCN = "被人突然从背后抱住，肯定是会被吓到的吧……"
L29_1.m_Talk_DEU = "Würdest du dich nicht erschrecken, wenn jemand dich plötzlich von hinten umarmt?"
L29_1.m_Talk_FRA = "Toi aussi tu serais surprise si quelqu'un t'attrapait par derrière comme ça sans crier gare, non ?"
L30_1 = {}
L30_1.m_CutScenKey_Talk = "EP1_ACT2_STAGE1_START@30#Talk"
L30_1.m_CutScenProcessKey = 30
L30_1.m_CutScenID = 18
L30_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "SEOYOON_ALT_NULL_NULL"
L30_1.m_Pos = "R"
L30_1.m_Talk_KOREA = "그야 약간의 스킨십은 좋은 관계를 유지하는 데 필수적인 요소니까?"
L30_1.m_fTalkTime = 0.03
L30_1.m_Talk_JPN = "でも、スキンシップって、良い関係を築くには欠かせないもん。"
L30_1.m_Talk_ENG = "A little hug never hurt anybody! It strengthens your relationship!"
L30_1.m_Talk_TWN = "要維持良好關係，一點親密接觸是不可少的吧？"
L30_1.m_Talk_THA = "การกอดไม่เคยทำร้ายใครนะ! แถมยังกระชับความสัมพันธ์ให้แนบแน่นด้วย!"
L30_1.m_Talk_VTN = "Ôm một chút thì đã làm sao nào! Một cái ôm sẽ giúp gia tăng tình cảm giữa bạn bè đấy!"
L30_1.m_Talk_SCN = "要维持良好关系当然需要一点身体接触啦？"
L30_1.m_Talk_DEU = "Eine kleine Umarmung hat noch niemandem geschadet! Es stärkt die Beziehung!"
L30_1.m_Talk_FRA = "Un petit câlin n'a jamais fait de mal à personne ! Ça renforce les relations."
