L41_1.m_Talk_VTN = L42_1
L42_1 = "比如说……公司里谁比较好说话，"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Zum Beispiel … Wem muss man hier ich in den Arsch kriechen?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Je sais pas... à qui faire de la lèche par exemple ?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "EP1_ACT2_STAGE1_START@42#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 42
