L42_1.m_Pos = "R"
L43_1 = "아니면 누구한텐 거슬리지 말아야 한다거나."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "あの人は要注意だとか。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Who I should avoid? Things like that?"
L42_1.m_Talk_ENG = L43_1
L43_1 = "或者誰的命令不能違抗之類的。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ควรหลบให้พ้นจากใครดี? อะไรประมาณนั้นน่ะ"
L42_1.m_Talk_THA = L43_1
L43_1 = "Nên tránh né ai? Kiểu kiểu vậy đó?"
L42_1.m_Talk_VTN = L43_1
L43_1 = "或者谁的命令不能违抗之类的。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Wem sollte ich aus dem Weg gehen, und so weiter?"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Qui il vaut mieux éviter ? Ce genre de choses ?"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "EP1_ACT2_STAGE1_START@43#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 43
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 18
L43_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
