L43_1.m_Pos = "L"
L44_1 = "미안하지만 나도 신입이라 특별히 가르쳐 줄 게 없어."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "悪いけど、私も新人だから、教えられることがないんだよね。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Sorry... I'm new too, so I'm in the same boat as you."
L43_1.m_Talk_ENG = L44_1
L44_1 = "不好意思，我也是個新人，沒什麼能教妳的。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "โทษทีนะ... ฉันก็เพิ่งมาทำงานที่นี่เหมือนกัน เพราะงั้นฉันก็ตกที่นั่งเดียวกับเธอนั่นแหละ"
L43_1.m_Talk_THA = L44_1
L44_1 = "Xin lỗi nhé... Tôi cũng là người mới, nên tôi cũng như cậu thôi."
L43_1.m_Talk_VTN = L44_1
L44_1 = "不好意思，我也是新人，没什么能教你的。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Tut mir leid, ich bin auch neu. Wir sitzen also im selben Boot."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Désolée... Je suis nouvelle moi aussi, je n'en sais pas plus que toi."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
