L44_1.m_Pos = "L"
L45_1 = "주시윤이라는 녀석과 엮이면 피곤하다는 것 정도?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "アキヤマ・シリュウという奴と一緒になると面倒ってことくらいかな？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "All I know is that Shiyoon guy gets annoying real fast."
L44_1.m_Talk_ENG = L45_1
L45_1 = "真要說的話，要小心一個叫周時雲的傢伙，跟他待在一起會很累喔。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "แต่ที่แน่ๆ อย่างนึงก็คือ เจ้าชิยุนนั่นเป็นคนที่น่าหงุดหงิดเป็นบ้าเลยล่ะ"
L44_1.m_Talk_THA = L45_1
L45_1 = "Tất cả những gì tôi biết là anh chàng Shiyoon đó rất nhanh sẽ làm cậu khó chịu đấy."
L44_1.m_Talk_VTN = L45_1
L45_1 = "非要说的话，要小心一个叫周时云的家伙，跟他待在一起会很累。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Ich weiß nur, dass dieser Shiyoon eine ziemliche Nervensäge ist."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Tout ce que je sais c'est que ce type nommé Charles peut très vite te casser les pieds."
L44_1.m_Talk_FRA = L45_1
