L47_1 = "신입은 아무래도 신입끼리 잘 통하는 부분이 있는 거지."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "やっぱり新人同士は通じるところがあるからね。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "We'll have to stick together since we're both new."
L46_1.m_Talk_ENG = L47_1
L47_1 = "我們都是新人的話就更合得來吧。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ในเมื่อเราเป็นเด็กใหม่ทั้งคู่ เราก็ควรจะสนิทกันไว้นะ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Chúng ta sẽ phải đoàn kết vì cả hai chúng ta đều là người mới."
