L7_1 = "펜릴 소대라면 관리국에서 정식 라이선스를 받은 팀이잖아?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "フェンリル小隊といえば、管理局から正式ライセンスをもらったチームでしょ？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "The Fenrir Squad is officially licensed by the Administration!"
L6_1.m_Talk_ENG = L7_1
L7_1 = "芬里爾小隊不是那個有管理局正式執照的小隊嗎？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "หน่วยเฟนเรียร์น่ะ ได้รับใบอนุญาตอย่างเป็นทางการจากองค์การบริหารโลกเลยนะ!"
L6_1.m_Talk_THA = L7_1
L7_1 = "Tiểu Đội Fenrir có giấy phép chính thức từ Cục Quản Lý đấy!"
L6_1.m_Talk_VTN = L7_1
L7_1 = "芬里尔小队不是那个有管理局正式执照的小队吗？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Der Fenrir-Trupp ist offiziell von der Administration lizenziert!"
L6_1.m_Talk_DEU = L7_1
L7_1 = "L'escouade Fenrir est officiellement agréée par l'Administration !"
L6_1.m_Talk_FRA = L7_1
