L17_1 = "<color=#ffd34c>เคาน์เตอร์ทุกคนในยานโปรดทราบ</color>"
L16_1.m_Talk_THA = L17_1
L17_1 = "<color=#ffd34c>Tất cả Counter trên tàu chú ý.</color>"
L16_1.m_Talk_VTN = L17_1
L17_1 = "<color=#ffd34c>通知船内各位制裁者要员。</color>"
L16_1.m_Talk_SCN = L17_1
L17_1 = "<color=#ffd34c>Achtung, alle Counter an Bord.</color>"
L16_1.m_Talk_DEU = L17_1
L17_1 = "<color=#ffd34c>À tous les Counters à bord.</color>"
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "EP1_ACT2_STAGE1_START@67#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 67
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 18
L17_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "<color=#ffd34c>곧 브리핑이 시작될 예정입니다.</color>"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "<color=#ffd34c>まもなくブリーフィングを開始します。</color>"
L17_1.m_Talk_JPN = L18_1
L18_1 = "<color=#ffd34c>The briefing will begin shortly.</color>"
L17_1.m_Talk_ENG = L18_1
L18_1 = "<color=#ffd34c>即將進行任務簡報。</color>"
L17_1.m_Talk_TWN = L18_1
L18_1 = "<color=#ffd34c>การชี้แจงรายละเอียดภารกิจจะเริ่มขึ้นแล้ว</color>"
L17_1.m_Talk_THA = L18_1
L18_1 = "<color=#ffd34c>Cuộc họp giao ban sẽ sớm bắt đầu.</color>"
L17_1.m_Talk_VTN = L18_1
L18_1 = "<color=#ffd34c>即将进行任务简报</color>"
L17_1.m_Talk_SCN = L18_1
L18_1 = "<color=#ffd34c>Das Briefing beginnt in Kürze.</color>"
L17_1.m_Talk_DEU = L18_1
L18_1 = "<color=#ffd34c>Le briefing va bientôt commencer.</color>"
L17_1.m_Talk_FRA = L18_1
