L19_1 = "EP1_ACT2_STAGE1_START@68#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 68
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 18
L18_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "<color=#ffd34c>방송을 들은 카운터 요원들은 즉시 작전실로 모여주시기 바랍니다.</color>"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "<color=#ffd34c>この放送を聞いたカウンター要員は、ただちに作戦室へお集まりください。</color>"
L18_1.m_Talk_JPN = L19_1
L19_1 = "<color=#ffd34c>All Counters hearing this announcement must gather in the Ops Room immediately.</color>"
L18_1.m_Talk_ENG = L19_1
L19_1 = "<color=#ffd34c>請聽到該廣播的制裁者至作戰室集合。</color>"
L18_1.m_Talk_TWN = L19_1
L19_1 = "<color=#ffd34c>เคาน์เตอร์ทุกคนที่ได้ยินประกาศนี้ โปรดเข้าประชุมที่ห้องปฏิบัติการโดยด่วน</color>"
L18_1.m_Talk_THA = L19_1
L19_1 = "<color=#ffd34c>Tất cả Counter nghe được thông báo này phải tập hợp tại Phòng Điều Hành ngay lập tức.</color>"
L18_1.m_Talk_VTN = L19_1
L19_1 = "<color=#ffd34c>请听到该条广播的各位制裁者到作战室集合。</color>"
L18_1.m_Talk_SCN = L19_1
L19_1 = "<color=#ffd34c>Alle Counter, die diese Durchsage hören, müssen sich sofort im Einsatzraum einfinden.</color>"
L18_1.m_Talk_DEU = L19_1
L19_1 = "<color=#ffd34c>Rassemblement immédiat dans la salle des opérations.</color>"
L18_1.m_Talk_FRA = L19_1
