L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "前回、第3種の侵食体を片づけた件は覚えているでしょう。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Do you remember defeating the Category 3 Corrupted Object last time?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "各位還記得上次解決掉3級侵蝕體的事嗎？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "จำที่เรากำจัดวัตถุคอร์รัปต์คลาส 3 คราวที่แล้วได้ใช่มั้ย?"
L36_1.m_Talk_THA = L37_1
L37_1 = "Các bạn có nhớ vụ đánh bại Đối Tượng Bị Ăn Mòn Loại 3 lần trước không?"
L36_1.m_Talk_VTN = L37_1
L37_1 = "各位还记得上次解决掉3级侵蚀体的事吗？"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Erinnerst du dich, dass du letztes Mal ein Counterside-Objekt der Kategorie 3 besiegt hast?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Vous vous souvenez de l'objet corrompu de catégorie 3 que vous avez abattu la dernière fois ?"
L36_1.m_Talk_FRA = L37_1
