L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "C"
L38_1 = "그와 관련하여, 관리국에서 새로운 의뢰가 왔습니다."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "それに関連して、管理局から新しい依頼が来ています。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "We have a new request from the Administration regarding that."
L37_1.m_Talk_ENG = L38_1
L38_1 = "管理局這次發來了與它相關的新委託。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "องค์การบริหารโลกมีงานใหม่มาให้เราเกี่ยวกับเรื่องนั้น"
L37_1.m_Talk_THA = L38_1
L38_1 = "Chúng ta có một yêu cầu mới liên quan đến vụ đó từ Cục Quản Lý."
L37_1.m_Talk_VTN = L38_1
L38_1 = "管理局这次发来了与之相关的新委托。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Dazu liegt uns ein neuer Auftrag der Administration vor."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Nous venons de recevoir une nouvelle requête de la part de l'Administration à ce sujet."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "EP1_ACT2_STAGE1_START@88#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 88
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 18
L38_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "C"
L39_1 = "아시다시피, 펜릴 소대의 활약으로 현실세계에 부상한 제 3종 침식체를 격파하긴 했지만 해당 지역은 여전히 CSE 3레벨을 유지하고 있습니다."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "ご存知のとおり、フェンリル小隊の活躍で現実世界に浮上した第3種の侵食体を撃破しましたが、そのエリアは依然としてCSE レベル3を維持しています。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "As you already know, Fenrir Squad managed to defeat the Category 3 C.O. that floated into the our dimension, but this area is still at CSE Level 3."
L38_1.m_Talk_ENG = L39_1
L39_1 = "我想大家也都知道，雖然芬里爾小隊漂亮地擊敗了躍出現世的3級侵蝕體，但該地區的CSE等級仍維持在3級。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "อย่างที่พวกเธอรู้แล้ว หน่วยเฟนเรียร์กำจัดวัตถุคอร์รัปต์คลาส 3 ที่ข้ามมาในมิติของเราได้สำเร็จ แต่พื้นที่ในส่วนนั้นก็ยังถูกคุกคามด้วย CSE ระดับ 3 อยู่ดี"
L38_1.m_Talk_THA = L39_1
L39_1 = "Như các bạn đã biết, Tiểu Đội Fenrir đã cố gắng đánh bại V.T.B.A.M. Loại 3 trôi nổi trong không gian của chúng ta, nhưng Cấp CSE của khu vực đó vẫn là Cấp 3."
L38_1.m_Talk_VTN = L39_1
L39_1 = "我想大家也都知道，虽然芬里尔小队出色的击败了跃出现世的3级侵蚀体，但该地区的CSE等级仍然维持在3级。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Wie ihr wisst, konnte der Fenrir-Trupp das C. O. der Kategorie 3 besiegen, das in unsere Dimension schwebte. Aber dieses Gebiet ist immer noch auf CSE-Stufe 3."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Comme vous le savez déjà, l'escouade Fenrir a réussi à abattre l'O.C. de catégorie 3 qui entrait dans notre dimension, mais cette zone a toujours un ECM niveau 3."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "EP1_ACT2_STAGE1_START@89#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 89
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 18
L39_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "C"
L40_1 = "관리국에서는 해당 지역 좌표와 연결된 이면세계에 침식 오염을 발생시키는 침식 코어가 존재할 거라고 추측하고 있습니다."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "管理局ではその地域の座標とつながるカウンターサイドに、侵食汚染を起こす侵食コアが存在すると推測しています。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "The Administration believes there may be a Corruption Core that's causing this corruption in the Counterside that's connected to the coordinates of that area."
L39_1.m_Talk_ENG = L40_1
L40_1 = "管理局推測，異界與該地區座標相連的區域中，應該存在著導致侵蝕污染的侵蝕核心。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "องค์การบริหารโลกเชื่อว่าอาจมีแกนคอร์รัปชั่นเป็นตัวการทำให้เกิดคอร์รัปชั่นจากฝั่งเคาน์เตอร์ไซด์ในพิกัดเดียวกับพื้นที่ดังกล่าว"
L39_1.m_Talk_THA = L40_1
L40_1 = "Cục Quản Lý tin rằng có thể có một Lõi Mòn đang gây ra sự ăn mòn ở các Counterside được kết nối với tọa độ của khu vực đó."
L39_1.m_Talk_VTN = L40_1
L40_1 = "管理局推测，异界与该地区坐标相连的区域中,应该存在导致侵蚀污染的侵蚀核心。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Die Administration geht davon aus, dass es einen Verderbniskern gibt, der diese Verderbnis auf der Counterside verursacht, und der mit den Koordinaten dieses Gebiets verbunden ist."
L39_1.m_Talk_DEU = L40_1
L40_1 = "L'Administration pense qu'un noyau de corruption qui provoque tout cela pourrait se trouver aux coordonnées reliées à cette zone dans le Contremonde."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
