L41_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "C"
L41_1 = "우리에게 내려온 임무는 침식 오염 정화를 위해 이면세계로 다이브해서 해당 침식 코어를 추적, 파괴하는 것입니다."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "私たちの任務は、侵食汚染浄化のためにカウンターサイドにダイブする。そして、ターゲットの侵食コアを追跡して破壊することです。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Our mission is to dive into the Counterside to purify the corruption, then track down and destroy the Corruption Core."
L40_1.m_Talk_ENG = L41_1
L41_1 = "所以這次我們的任務是淨化侵蝕污染。為此我們需要躍入異界，追蹤並破壞該侵蝕核心。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ภารกิจของเราคือการไดฟ์เข้าไปในเคาน์เตอร์ไซด์เพื่อชำระคอร์รัปชั่น จากนั้นก็ให้ตามหาและทำลายแกนคอร์รัปชั่น"
L40_1.m_Talk_THA = L41_1
L41_1 = "Nhiệm vụ của chúng ta là lặn xuống Counterside để thanh lọc sự ăn mòn, sau đó truy tìm và tiêu diệt Lõi Mòn."
L40_1.m_Talk_VTN = L41_1
L41_1 = "这次我们的任务是净化侵蚀污染。为此我们需要跃入异界，追踪并破坏该侵蚀核心。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Unsere Aufgabe ist es, in die Counterside einzutauchen, um die Verderbnis zu läutern, den Verderbniskern aufzuspüren und zu zerstören."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Notre mission est de plonger dans le Contremonde pour purifier la corruption, puis de traquer et de détruire le noyau de corruption."
L40_1.m_Talk_FRA = L41_1
