L44_1 = "เราก็เลยจ้างหน่วยเคาน์เตอร์หน่วยที่ 2 มาช่วยในภารกิจครั้งนี้"
L43_1.m_Talk_THA = L44_1
L44_1 = "Chúng ta đã thuê thêm một Tiểu đội Counter thứ hai để tạo điều kiện thuận lợi cho các nhiệm vụ của chúng ta."
