L48_1 = "이번에 코핀 컴퍼니에 합류한 알트소대의 리더, 서윤입니다."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "この度コフィンカンパニーに入社したアルト小隊リーダーのシズカです。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "My name is Seo Yoon. I'll be leading the new ALT Squad for the Coffin Company."
