L48_1 = "我是這次加入科芬公司的阿爾特小隊隊長，徐芸。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ฉันชื่อซอ ยุน ตั้งแต่วันนี้ไป ฉันจะเป็นผู้นำหน่วย ALT ออกปฏิบัติการในฐานะพนักงานของบริษัทคอฟฟินค่ะ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Tôi tên là Seo Yoon. Tôi sẽ lãnh đạo Tiểu Đội ALT của Công Ty Coffin."
L47_1.m_Talk_VTN = L48_1
L48_1 = "我是这次加入科芬公司的阿尔特小队队长，徐芸。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Mein Name ist Seo Yoon. Ich führe den neuen ALT-Trupp der Coffin Company."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Je m'appelle Seo Yoon. Je serai à la tête de la nouvelle escouade ALT de la Compagnie Coffin."
