L50_1 = "참고로 펜릴 소대의 이야기는 여기저기서 많이 들었습니다."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "ちなみに、フェンリル小隊のことはあちこちで色々聞きました。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "I've heard a lot about the Fenrir Squad here and there."
L49_1.m_Talk_ENG = L50_1
L50_1 = "我聽說過許多芬里爾小隊的傳聞。"
L49_1.m_Talk_TWN = L50_1
