L49_1.m_Talk_THA = L50_1
L50_1 = "Tôi đã nghe nói rất nhiều về Tiểu Đội Fenrir ở khắp mọi nơi."
L49_1.m_Talk_VTN = L50_1
L50_1 = "我听说过许多芬里尔小队的传闻，"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Ich habe schon viel über den Fenrir-Trupp gehört."
L49_1.m_Talk_DEU = L50_1
L50_1 = "J'ai beaucoup entendu parler de l'escouade Fenrir."
L49_1.m_Talk_FRA = L50_1
