L4_1 = "하하하, 스승님. 우리 팬이래요."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "ハハハ、師匠、僕たちのファンですって。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Hahaha, Master. She said she's our fan."
L3_1.m_Talk_ENG = L4_1
L4_1 = "哈哈哈，師父，她說她是我們的粉絲耶。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ฮะฮะฮะ อาจารย์ครับ เธอบอกว่าเธอเป็นแฟนคลับพวกเราล่ะครับ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Hahaha, Sếp. Cô ấy nói ngưỡng mộ chúng ta kìa."
L3_1.m_Talk_VTN = L4_1
L4_1 = "哈哈哈，老师，她说她是我们的粉丝哎。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Haha, Meisterin … Sie sagte, sie sei ein Fan von uns."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Ha ha ha, maître. Elle a dit qu'elle nous admirait."
L3_1.m_Talk_FRA = L4_1
