L5_1 = "EP1_ACT2_STAGE1_START@104#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 104
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 18
L4_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L4_1.m_Pos = "L"
L5_1 = "이것 참 부끄럽네요. 대체 무슨 이야기를 들었던 걸까요?"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "照れるな……いったいどんな話を聞いたんでしょうかね。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "That made me blush. I wonder what she heard about us?"
L4_1.m_Talk_ENG = L5_1
L5_1 = "好害羞喔，不知道她聽到的是怎樣的傳聞呀？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ทำเอาเขินเลยล่ะ ว่าแต่เธอรู้เรื่องอะไรเกี่ยวกับพวกเราบ้างนะ?"
L4_1.m_Talk_THA = L5_1
L5_1 = "Cô ấy làm tôi mắc cỡ ghê. Tôi tự hỏi cô ấy đã nghe những gì về chúng ta nhỉ?"
L4_1.m_Talk_VTN = L5_1
L5_1 = "还有点害羞呢，不知道你听到的是怎样的传闻呀？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Da laufe ich ja fast rot an … Ich frage mich, was sie über uns gehört hat."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Ça m'a fait rougir. Je me demande ce qu'elle a pu entendre à notre sujet."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
