L6_1 = "Who cares... I bet it's nothing good, anyway..."
L5_1.m_Talk_ENG = L6_1
L6_1 = "知道這個幹什麼……而且我不覺得會是什麼好事……"
L5_1.m_Talk_TWN = L6_1
L6_1 = "จะไปสนทำไมกันล่ะ... ฉันว่าน่าจะมีแต่เรื่องแย่ๆ นั่นแหละ..."
L5_1.m_Talk_THA = L6_1
L6_1 = "Ai mà quan tâm chứ... Dù gì thì cũng chẳng phải là tin tốt đâu, ta cá đấy..."
L5_1.m_Talk_VTN = L6_1
L6_1 = "知道这个干什么……反正估计也没什么好话……"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Wen interessiert das? Es war bestimmt nichts Gutes …"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Quelle importance ? Je parie que ce n'est rien de bon, de toute façon..."
L5_1.m_Talk_FRA = L6_1
