L21_1 = "YOOJIN_ALT_NULL_NULL"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "L"
L21_1 = "어디서 끼어들어? 내 말 아직 안 끝났다고!!"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "割り込んでくるなよ。 俺の話、まだ途中だろうが！！"
L20_1.m_Talk_JPN = L21_1
L21_1 = "How dare you cut me off! I never said I'm done!!!"
L20_1.m_Talk_ENG = L21_1
L21_1 = "妳插什麼嘴啊？我還沒說完好嗎！！"
L20_1.m_Talk_TWN = L21_1
L21_1 = "กล้าดียังไงมาตัดหน้าฉันเนี่ย! ฉันยังไม่ได้บอกเลยนะว่าพูดจบแล้ว!!!"
L20_1.m_Talk_THA = L21_1
L21_1 = "Sao cậu dám ngắt lời tôi hả! Tôi chưa bảo là mình đã nói xong đâu nhé!!!"
L20_1.m_Talk_VTN = L21_1
L21_1 = "你插什么嘴啊？我还没说完好吗！！"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Was fällt dir ein, mich zu unterbrechen? Ich habe nie gesagt, dass ich fertig bin!"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Ça va pas de me passer devant comme ça ? J'ai jamais dit que j'avais fini !!!"
L20_1.m_Talk_FRA = L21_1
