L26_1 = "XIAOLIN_ALT_NULL_NULL"
L25_1.m_CharStrID = L26_1
L25_1.m_Pos = "R"
L26_1 = "시끄러워. 진화도 덜 된 곰 같은 게."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "うるさいわね。クマみたいな体して、人間に進化してから来な。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Oh, shut up. You clumsy bear."
L25_1.m_Talk_ENG = L26_1
L26_1 = "吵死了，妳這像熊一樣缺乏進化的東西。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "เฮ้อ หุบปากได้แล้วน่า ยัยหมีเซ่อซ่า"
L25_1.m_Talk_THA = L26_1
L26_1 = "Ôi thôi im đi. Đồ to xác rẻ tiền."
L25_1.m_Talk_VTN = L26_1
L26_1 = "吵死了，你这只猴子，去进化两轮再来说话吧。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Ach, sei still, du Trantüte."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Oh, ferme-la. Grosse balourde."
L25_1.m_Talk_FRA = L26_1
