L27_1 = "EP1_ACT2_STAGE1_START@126#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 126
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 18
L26_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "XIAOLIN_ALT_NULL_NULL"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "R"
L27_1 = "그리고 그 우어우어 거리는 말 비슷한 웅얼거림은 대체 뭐야?"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "あと、図体に見合わないその喋り方はなに？　もごもご、ぼそぼそ……"
L26_1.m_Talk_JPN = L27_1
L27_1 = "I can't even understand what you're saying through your stupid mumbling."
L26_1.m_Talk_ENG = L27_1
L27_1 = "還有妳那是在說話嗎？結結巴巴的到底想說什麼啊？"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ที่พูดงึมงำเมื่อกี้มันอะไรของเธอน่ะ ฟังไม่รู้เรื่องด้วยซ้ำ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Tôi thậm chí còn không thể hiểu những gì cậu nói bằng những lời lẩm bẩm ngu ngốc đó nữa."
L26_1.m_Talk_VTN = L27_1
L27_1 = "还有你那是在说话吗？磕磕巴巴的到底想说什么啊？"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Ich kann nicht mal verstehen, was du da vor dich hin murmelst."
L26_1.m_Talk_DEU = L27_1
L27_1 = "C'est tout juste si on parvient à comprendre ce que tu marmonnes dans ta barbe."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "EP1_ACT2_STAGE1_START@127#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 127
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 18
L27_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "XIAOLIN_ALT_NULL_NULL"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "R"
L28_1 = "듣는 사람에게 민폐라는 생각은 해 본 적 없어?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "聞いてる側に迷惑だと思わないわけ？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "You ever think about what a moron you sound like?"
L27_1.m_Talk_ENG = L28_1
L28_1 = "妳不覺得妳造成聽眾很大的困擾嗎？"
L27_1.m_Talk_TWN = L28_1
L28_1 = "รู้มั้ยว่ามันดูน่าอนาถแค่ไหน?"
L27_1.m_Talk_THA = L28_1
