L36_1.m_Pos = "R"
L37_1 = "......넌 왜 이럴 때만 쓸데없이 준비성이 좋은 거냐?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "……お前って、こんな時だけムダに準備が良いよな。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "...Why are you always so well-prepared in these useless situations?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "……為什麼只有這種時候，你才會準備得特別周到啊？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "...ทีเรื่องไร้สาระแบบนี้ เตรียมพร้อมมาดีเชียวนะ"
L36_1.m_Talk_THA = L37_1
L37_1 = "...Tại sao cậu lại luôn chuẩn bị đầy đủ cho những tình huống vô dụng như vậy thế hả?"
L36_1.m_Talk_VTN = L37_1
L37_1 = "……为什么只有这种时候，你才会准备的这么周到啊？"
L36_1.m_Talk_SCN = L37_1
L37_1 = "… Warum bist du auf diese unnützen Situationen immer so gut vorbereitet?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "... Pourquoi êtes-vous toujours si bien préparé pour ces situations inutiles ?"
L36_1.m_Talk_FRA = L37_1
