L40_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "C"
L40_1 = "펜릴 팀과 호흡이 아주 잘 맞을 것 같군요."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "フェンリルチームと息ピッタリになりそうだわ。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "You guys are a perfect match for the Fenrir Team."
L39_1.m_Talk_ENG = L40_1
L40_1 = "看來和芬里爾小隊很合拍喔。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "แบบนี้จะต้องเข้าขากับทีมเฟนเรียร์ได้อย่างเพอร์เฟ็กต์เลยล่ะ"
L39_1.m_Talk_THA = L40_1
L40_1 = "Các bạn là những mảnh ghép hoàn hảo cho Đội Fenrir."
L39_1.m_Talk_VTN = L40_1
L40_1 = "应该会与芬里尔小队有相当默契的配合吧。"
