L41_1 = "EP1_ACT2_STAGE1_START@140#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 18
L40_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "C"
L41_1 = "알트 소대는 아직 정식 프로 라이선스를 취득한 팀은 아닙니다."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "アルト小隊はまだ正式なプロライセンスを取得したわけではありません。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "The ALT Squad doesn't have an official pro license yet."
L40_1.m_Talk_ENG = L41_1
L41_1 = "阿爾特小隊暫時還沒有取得正式的專業執照。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ตอนนี้หน่วย ALT ยังไม่มีใบอนุญาตอาชีพอย่างเป็นทางการ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Tiểu Đội ALT vẫn chưa có giấy phép chuyên nghiệp."
L40_1.m_Talk_VTN = L41_1
L41_1 = "阿尔特小队暂时还没有取得正式的专业执照，"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Der ALT-Trupp hat noch keine offizielle Profilizenz."
L40_1.m_Talk_DEU = L41_1
L41_1 = "L'escouade ALT n'a pas encore sa licence professionnelle officielle."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "EP1_ACT2_STAGE1_START@141#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 141
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 18
L41_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "C"
L42_1 = "하지만 전원 B등급 이상의 카운터로 구성된, 언더그라운드에서는 꽤 알아주는 카운터 소대입니다."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "ですが、全員B級以上のカウンターで、アンダーグラウンドでは名の知れたカウンター小隊です。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "But their team is full of Grade B Counters or better, and they've already made a name for themselves among the non-licensed, \"underground\" teams."
L41_1.m_Talk_ENG = L42_1
L42_1 = "但是小隊隊員都是B級以上的制裁者，而且都相當瞭解地下世界。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "แต่ทีมของพวกเธอก็มีสมาชิกเป็นเคาน์เตอร์เกรดไม่ต่ำกว่า B ทั้งนั้น นอกจากนี้ยังมีชื่อเสียงโด่งดังในหมู่ทีม \"ใต้ดิน\" ที่ไม่มีใบอนุญาต"
L41_1.m_Talk_THA = L42_1
L42_1 = "Nhưng các thành viên trong đội của họ đều là Counter Hạng B hoặc cao hơn, và họ đã tự gây dựng danh tiếng cho mình trong số các đội \"thế giới ngầm\" không được cấp phép."
L41_1.m_Talk_VTN = L42_1
L42_1 = "但是小队队员都是B级以上的制裁者，而且都非常了解地下世界，"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Aber ihr Team besteht aus Countern der Klasse B oder besser, und sie haben sich bereits einen Namen unter den nicht lizenzierten Untergrundteams gemacht."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Mais elle est composée de Counters de grade B ou supérieur, et elle s'est déjà fait un nom parmi les équipes non officielles du « souterrain »."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "EP1_ACT2_STAGE1_START@142#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 18
L42_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "C"
L43_1 = "지금처럼 실적을 쌓아가면 내년쯤에는 무난하게 라이선스를 따겠죠."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "このまま実績さえ積めれば、来年くらいには難なくライセンスを取得するでしょう。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "I'm sure you'll get your license by next year if all goes well."
L42_1.m_Talk_ENG = L43_1
L43_1 = "只要繼續積累業績，明年要拿到執照應該不是什麼困難的事情。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ฉันมั่นใจว่าถ้าทุกอย่างไปได้สวย ปีหน้าก็คงจะขอใบอนุญาตให้พวกเธอได้"
L42_1.m_Talk_THA = L43_1
L43_1 = "Tôi chắc chắn các bạn sẽ nhận được giấy phép vào năm tới nếu mọi việc suôn sẻ."
L42_1.m_Talk_VTN = L43_1
L43_1 = "只要继续积累业绩，明年要拿到执照应该不是什么困难的事情。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Ich bin sicher, dass ihr nächstes Jahr eure Lizenz bekommen werdet, wenn alles gut läuft."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Je suis certaine que vous obtiendrez votre licence d'ici l'année prochaine si tout va bien."
L42_1.m_Talk_FRA = L43_1
