L8_1 = "하하, 미나 양은 펜릴 소대의 수습대원으로 등록되어 있거든요."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "ハハ、ミナさんはフェンリル小隊の見習い隊員として登録されているんですよ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Heh, that's because you're registered as a probationary operative of the Fenrir Squad."
L7_1.m_Talk_ENG = L8_1
L8_1 = "哈哈，米娜小姐是用芬里爾小隊見習隊員的身份登記的呀。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "อ๋อ นั่นก็เพราะคุณลงทะเบียนเป็นเจ้าหน้าที่ฝึกงานของหน่วยเฟนเรียร์น่ะ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Heh, đó là bởi vì cậu đã được đăng ký làm nhân viên tập sự của Tiểu Đội Fenrir."
L7_1.m_Talk_VTN = L8_1
L8_1 = "哈哈，米娜小姐是以芬里尔小队见习队员的身份进行登记的呀。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Das liegt daran, dass du als Agentin auf Probe beim Fenrir-Trupp registriert bist."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Hé hé, c'est parce que tu es enregistrée en tant qu'agent probatoire de l'escouade Fenrir."
L7_1.m_Talk_FRA = L8_1
