L8_1.m_Talk_JPN = L9_1
L9_1 = "So your activities are sanctioned by the group license of the squad."
L8_1.m_Talk_ENG = L9_1
L9_1 = "妳適用的是團體執照，所以沒有問題喔。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "คุณเลยได้รับอนุญาตให้ออกปฏิบัติการ เพราะมีใบอนุญาตของหน่วยคอยสนับสนุนอยู่"
L8_1.m_Talk_THA = L9_1
L9_1 = "Vậy nên các hoạt động của cậu nằm trong quyền hạn chấp thuận giấy phép của tiểu đội."
L8_1.m_Talk_VTN = L9_1
L9_1 = "你适用的是团体执照，所以没有问题哦。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Deine Aktivitäten werden also durch die Gruppenlizenz des Trupps sanktioniert."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Tu es donc couverte par la licence du groupe."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "EP1_ACT2_STAGE1_START@159#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 159
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 18
L9_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L9_1.m_Pos = "R"
L10_1 = "원래는 라이선스가 없을 경우, 지도소대의 감독이 있어야만 정식 활동을 할 수가 있어요."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "本来はライセンスがない場合、担当小隊の監督なしでは正式な活動はできません。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Usually, supervision by a guidance squad is required for non-licensed Counters."
L9_1.m_Talk_ENG = L10_1
L10_1 = "本來如果沒有執照的話，小隊需要一個指揮的監督，才能作為正式制裁者小隊執行任務。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "โดยทั่วไปแล้ว เคาน์เตอร์ที่ยังไม่มีอนุญาตจะต้องอยู่ภายใต้การดูแลของหน่วยเคาน์เตอร์อาชีพอย่างเรา"
L9_1.m_Talk_THA = L10_1
L10_1 = "Thông thường, các Counter không có giấy phép cần có sự giám sát của một tiểu đội hướng dẫn."
L9_1.m_Talk_VTN = L10_1
L10_1 = "本来如果没有执照的话，小队需要一个指挥的监督，才能作为正式制裁者小队执行任务。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "In der Regel ist für nicht lizenzierte Counter eine Aufsicht durch einen Führungstrupp erforderlich."
L9_1.m_Talk_DEU = L10_1
L10_1 = "En général, une escouade de supervision est requise pour les Counters non licenciés."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "EP1_ACT2_STAGE1_START@160#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 160
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 18
L10_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L10_1.m_Pos = "R"
L11_1 = "물론 그런 거 신경 안 쓰는 미인증 회사들도 있긴 하지만요."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "もちろん、そんなの気にもしない未認定会社もありますけどね。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Of course, there are lots of uncertified companies that don't care about those rules."
L10_1.m_Talk_ENG = L11_1
L11_1 = "當然，那些未認證的公司是不在意這些東西的。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "แน่นอนว่าก็มีบริษัทที่ไม่มีอนุญาตอีกหลายแห่งที่ไม่สนใจกฎพวกนั้น"
L10_1.m_Talk_THA = L11_1
L11_1 = "Tất nhiên, rất nhiều công ty không được cấp phép chẳng hề quan tâm đến những quy tắc đó."
L10_1.m_Talk_VTN = L11_1
L11_1 = "当然，也有些未认证公司是不在意这些东西的。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Es gibt allerdings reichlich nicht zertifizierte Unternehmen, denen diese Regeln egal zu sein scheinen."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Mais bien sûr, il existe un grand nombre d'entreprises non homologuées qui ne respectent pas ces règles."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
