L14_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "C"
L14_1 = "그리고 작전부에도 신규 인원을 충원했습니다."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "あと、作戦部にも新規メンバーを増員しました。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "I also hired new people for the Operation Department."
L13_1.m_Talk_ENG = L14_1
L14_1 = "另外，我們的作戰部也有新員工加入，自我介紹一下吧。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "นอกจากนี้ ฉันยังจ้างพนักงานใหม่ให้มาช่วยงานที่แผนกปฏิบัติการด้วย"
L13_1.m_Talk_THA = L14_1
L14_1 = "Tôi cũng đã thuê thêm người mới cho Bộ Phận Điều Hành."
L13_1.m_Talk_VTN = L14_1
L14_1 = "另外，作战部也有新员工加入。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Ich habe zudem neue Mitarbeiter für die Einsatzabteilung eingestellt."
L13_1.m_Talk_DEU = L14_1
L14_1 = "J'ai également embauché de nouvelles recrues pour le département des opérations."
L13_1.m_Talk_FRA = L14_1
