L17_1 = "LENA_COFFIN_NULL_NULL"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "L"
L17_1 = "앞으로 작전부에서 여러분을 도와드릴 레나입니다."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "これから作戦部で皆さんのサポート役をつとめるレナです。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "My name is Lena. I'll be supporting you from the Operation Department."
L16_1.m_Talk_ENG = L17_1
L17_1 = "我是作戰部的蕾娜，往後會在作戰部協助大家。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ฉันชื่อเลน่า มีหน้าที่ช่วยเหลือพวกคุณจากแผนกปฏิบัติการค่ะ"
L16_1.m_Talk_THA = L17_1
L17_1 = "Tôi tên là Lena. Tôi sẽ hỗ trợ các bạn từ Bộ Phận Điều Hành."
L16_1.m_Talk_VTN = L17_1
L17_1 = "我是作战部的蕾娜，往后会在作战部协助大家。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Mein Name ist Lena. Ich werde euch von der Einsatzabteilung aus unterstützen."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Je m'appelle Lena. Je vous apporterai mon soutien depuis le département des opérations."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "EP1_ACT2_STAGE1_START@167#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 167
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 18
L17_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "LENA_COFFIN_NULL_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "L"
L18_1 = "부족하지만 잘 부탁드립니다."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "未熟者ですが、よろしくお願いいたします。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "I still have a lot to learn, so I look forward to working with you."
L17_1.m_Talk_ENG = L18_1
L18_1 = "如果有不足的地方，還請大家多多指教。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ฉันยังต้องเรียนรู้สิ่งต่างๆ อีกมาก เพราะฉะนั้นฝากเนื้อฝากตัวด้วยนะคะ"
L17_1.m_Talk_THA = L18_1
L18_1 = "Tôi vẫn còn nhiều thứ phải học lắm, vậy nên rất mong được làm việc với các bạn."
L17_1.m_Talk_VTN = L18_1
L18_1 = "如果有不足的地方，还请多多关照。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Ich habe noch viel zu lernen und freue mich auf die Zusammenarbeit mit euch."
L17_1.m_Talk_DEU = L18_1
L18_1 = "J'ai encore beaucoup de choses à apprendre, alors j'ai hâte de travailler avec vous."
L17_1.m_Talk_FRA = L18_1
