L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "R"
L20_1 = "운명의 이끌림을 따라...... 이곳에 오게 되었습니다."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "運命の導きによって……こちらに参りました。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "I've followed destiny's beckoning... and ended up here."
L19_1.m_Talk_ENG = L20_1
L20_1 = "我跟隨命運的指引……來到了這裡。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ฉันเดินทางมาตามเสียงเรียกแห่งโชคชะตา... ก็เลยมาลงเอยที่นี่"
L19_1.m_Talk_THA = L20_1
L20_1 = "Tôi từng đi theo tiếng gọi của vận mệnh... và kết thúc ở đây."
L19_1.m_Talk_VTN = L20_1
L20_1 = "我跟随着命运的指引……来到了这里。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Ich bin dem Ruf der Bestimmung gefolgt … und hier gelandet."
L19_1.m_Talk_DEU = L20_1
L20_1 = "J'ai suivi l'appel du destin... et me suis retrouvée ici."
L19_1.m_Talk_FRA = L20_1
