L26_1 = "다들 관상을 보니 파괴와 파멸과 파란의 대흉조가 느껴지시는 분들이 많네요."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "皆さんの人相を見るかぎり、破壊と破滅、波乱の大凶星が感じられる方が多いですね。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Looking at your faces, I can sense an ill omen of destruction, terror, and turmoil in many of you."
L25_1.m_Talk_ENG = L26_1
L26_1 = "看過各位的面相後，我從各位的臉上感受到了破壞、毀滅和危險的凶兆。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ดูจากใบหน้าของพวกคุณแล้ว ฉันสัมผัสได้ถึงลางร้ายแห่งการทำลายล้าง ความหวาดกลัว แล้วก็ความวุ่นวายปั่นป่วนอยู่ภายในตัวพวกคุณหลายคนเลยล่ะ"
L25_1.m_Talk_THA = L26_1
L26_1 = "Nhìn mặt các bạn, tôi có thể cảm nhận được những điềm xấu liên quan đến sự hủy diệt, khủng bố và hỗn loạn."
L25_1.m_Talk_VTN = L26_1
L26_1 = "看过各位的面相，我从许多位脸上感受到破坏、毁灭和艰险的凶兆。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Wenn ich in eure Gesichter schaue, beschleicht mich bei vielen ein ominöses Gefühl der Zerstörung, des Terrors und des Chaos."
L25_1.m_Talk_DEU = L26_1
L26_1 = "L'ombre de la destruction, de la terreur et du tourment plane sur nombre de vos visages... je peux le sentir."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "EP1_ACT2_STAGE1_START@176#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 176
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 18
L26_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "CHLOE_COFFIN_NULL_NULL"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "C"
L27_1 = "혹시 평소에 액운이 많이 낀다고 생각하시는 분들은 나중에 따로 찾아오시기 바랍니다."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "普段からやけに厄災が多いと感じる方がおられましたら、後ほど私を訪ねてきてください。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "If you've always wondered why you're always on the short end of the stick, come speak to me later."
L26_1.m_Talk_ENG = L27_1
L27_1 = "如果有人覺得自己平日厄運纏身，之後可以單獨來找我。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ถ้าเกิดคุณรู้สึกว่าตัวเองโชคไม่ดีอยู่ตลอดเวลา ก็มาปรึกษาเรื่องดวงชะตากับฉันได้ค่ะ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Nếu các bạn thắc mắc tại sao mình luôn bị chèn ép hay bị đối xử bất công, hãy đến nói chuyện với tôi sau buổi họp."
L26_1.m_Talk_VTN = L27_1
L27_1 = "如果有人觉得自己平日厄运缠身，希望之后可以单独来找我。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Falls ihr euch schon mal gefragt habt, warum ihr im Leben oft den Kürzeren zieht, dann kommt nachher zu mir."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Si vous avez l'impression d'être toujours sur la corde raide et que vous souhaitez en connaître la raison, venez me trouver."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "EP1_ACT2_STAGE1_START@177#Talk"
