L28_1 = "CHLOE_COFFIN_NULL_NULL"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "C"
L28_1 = "참고로 복채는 카드 결제도 가능......"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "ちなみに、お代はカード払いでも受け付けており……"
L27_1.m_Talk_JPN = L28_1
L28_1 = "I also accept credit cards for my services..."
L27_1.m_Talk_ENG = L28_1
L28_1 = "占卜費用也接受刷卡……"
L27_1.m_Talk_TWN = L28_1
L28_1 = "จ่ายด้วยบัตรเครดิตฉันก็รับนะคะ..."
L27_1.m_Talk_THA = L28_1
L28_1 = "Tôi cũng chấp nhận thẻ tín dụng cho các dịch vụ của mình..."
L27_1.m_Talk_VTN = L28_1
L28_1 = "占卜费的话也可以刷卡结……"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Ich akzeptiere auch Kreditkarten für meine Dienstleistungen."
L27_1.m_Talk_DEU = L28_1
L28_1 = "J'accepte également les cartes de crédit..."
L27_1.m_Talk_FRA = L28_1
