L30_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "C"
L30_1 = "업무 시간 중에 호객 행위는 자제해 주면 좋겠는데."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "業務時間中の客引きは控えてほしいわ。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "There will be no soliciting during work hours."
L29_1.m_Talk_ENG = L30_1
L30_1 = "希望妳在工作時間克制一下自己的拉客行為。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "บริษัทเราห้ามโฆษณางานนอกในระหว่างเวลางานนะ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Không được bán hàng đa cấp trong giờ làm việc nhé."
L29_1.m_Talk_VTN = L30_1
L30_1 = "希望您在工作时间克制一下自己拉客的行为。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Keine Werbung für andere Aktivitäten während der Arbeitszeit."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Il n'y aura pas de démarchage pendant les heures de travail."
L29_1.m_Talk_FRA = L30_1
