L34_1 = "EP1_ACT2_STAGE1_START@183#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 183
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 18
L33_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L33_1.m_bWaitClick = true
