L33_1.m_Face = "UNIT_HATE"
L33_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L33_1.m_Pos = "L"
L34_1 = "......여긴 대체 채용 기준이 어떻게 되어 먹은 거야?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "……いったい、ここの採用基準はどうなってるわけ？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "...Do you guys even screen people before you hire them?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "……這裡雇傭員工的標準到底是什麼啊？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "...ตอนรับพนักงานนี่ได้คัดคนมั่งมั้ยเนี่ย?"
L33_1.m_Talk_THA = L34_1
L34_1 = "...Các người có từng sàng lọc hồ sơ trước khi thuê họ không thế?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "……这里雇佣员工的标准到底是什么啊？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Sag mal, überprüft ihr die Leute eigentlich, bevor ihr sie anheuert?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "... Mais est-ce que vous filtrez les gens avant de les embaucher ?"
L33_1.m_Talk_FRA = L34_1
