L36_1 = "EP1_ACT2_STAGE1_START@185#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 185
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 18
L35_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "C"
L36_1 = "어쨌든, 제대로 된 임무를 맡은 건 정말 오랜만이군요."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "とにかく、まともな任務は久々ですね。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Anyhow! It's been a while since we got a proper mission."
L35_1.m_Talk_ENG = L36_1
L36_1 = "總之，我們已經很久沒有接過像樣的任務了。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "เอาล่ะ! เราไม่ได้ทำภารกิจแบบจริงๆ จังๆ มานานแล้วน่ะนะ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Sao cũng được! Cũng lâu rồi kể từ lần cuối chúng ta nhận được một nhiệm vụ thích hợp."
L35_1.m_Talk_VTN = L36_1
L36_1 = "总之，我们已经很久没有接过像样的任务了。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "… Wie dem auch sei, es ist eine Weile her, dass wir eine richtige Mission hatten."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Bref ! Nous n'avions pas eu de mission digne de ce nom depuis un bon moment."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP1_ACT2_STAGE1_START@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 18
L36_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "C"
L37_1 = "이 기회를 놓치지 않도록, 다들 최선을 다해 주시기 바랍니다."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "このチャンスを逃さないために、皆さん最善を尽くしてくださいね。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Let's not screw this up. I expect everyone to give it your best."
L36_1.m_Talk_ENG = L37_1
L37_1 = "請各位不要錯失這個機會，全力以赴吧。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "เพราะฉะนั้นอย่าทำพังล่ะ หวังว่าทุกคนจะพยายามเต็มที่นะ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Đừng làm hỏng việc nhé. Tôi hy vọng tất cả mọi người sẽ cố gắng hết sức."
L36_1.m_Talk_VTN = L37_1
L37_1 = "请各位不要浪费这个机会，全力以赴吧。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Lasst es uns nicht vermasseln. Ich erwarte von allen, dass sie ihr Bestes geben."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Essayons de ne pas tout gâcher. J'attends de chacun d'entre vous qu'il donne le meilleur de lui-même."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP1_ACT2_STAGE1_START@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 18
L37_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "C"
L38_1 = "안타깝지만 저는 처리해야 할 행정사항들이 많아서 작전 현장에는 동행하지 못할 것 같습니다."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "残念ですが、私には事務作業が\n溜まっていて、作戦現場に同行できそうにありません。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Unfortunately, I have some administrative matters to tend to, so I won't be on the frontlines with you."
L37_1.m_Talk_ENG = L38_1
L38_1 = "遺憾的是，我還有許多後勤事務要處理，所以沒辦法和大家一起去作戰現場。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "น่าเสียดายที่ฉันมีงานบริหารที่จะต้องดูแล ก็เลยอยู่แนวหน้ากับพวกเธอไม่ได้"
L37_1.m_Talk_THA = L38_1
L38_1 = "Thật không may, tôi có một số vấn đề hành chính cần phải giải quyết, vì vậy tôi sẽ không ở tuyến đầu cùng các bạn."
L37_1.m_Talk_VTN = L38_1
L38_1 = "很遗憾，因为我还有许多后勤事务要处理，就没办法和大家一起去作战现场了。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Ich muss leider einige administrative Angelegenheiten erledigen, sodass ich nicht mit euch an der Front sein werde."
L37_1.m_Talk_DEU = L38_1
L38_1 = "J'ai malheureusement quelques affaires administratives à régler, et ne serai donc pas avec vous en première ligne."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "EP1_ACT2_STAGE1_START@188#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 188
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 18
L38_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "C"
L39_1 = "대신, 만약의 사태를 대비해 기업부설 침식생물학 연구소의 올리비에 박 교수님이 여러분과 함께할 예정입니다."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "その代わり、万が一の場合に備えて、併設の侵食生物学研究所からオリヴィエ教授が同行する予定です。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "But Dr. Olivie Park from the Corruption Biology Research Lab will be joining you just in case."
L38_1.m_Talk_ENG = L39_1
L39_1 = "為了以防萬一，侵蝕生物學研究所的奧利維亞教授將與大家一起行動。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "แต่ ดร.โอลิวี่ พัค จากแล็บวิจัยชีววิทยาคอร์รัปชั่นจะมาช่วยเราในภารกิจนี้ด้วย เผื่อมีเหตุฉุกเฉินน่ะนะ"
L38_1.m_Talk_THA = L39_1
L39_1 = "Nhưng Tiến Sĩ Olivie Park từ Phòng Thí Nghiệm Nghiên Cứu Sinh Học Ăn Mòn sẽ tham gia cùng các bạn để phòng hờ."
L38_1.m_Talk_VTN = L39_1
L39_1 = "但为了以防万一，将会由侵蚀生物学研究所的奥利维亚教授与大家一起前往现场。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Aber Dr. Olivie Park vom Forschungslabor für Verderbnisbiologie wird sich euch anschließen – nur für alle Fälle."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Mais le docteur Olivie Park, du laboratoire de recherche en biologie de la corruption, se joindra à vous juste au cas où."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
