L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "R"
L42_1 = "반가워요, 여러분."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "皆さん、はじめまして。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "It's a pleasure to meet you all."
L41_1.m_Talk_ENG = L42_1
L42_1 = "大家好。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ยินดีที่ได้รู้จักนะ ทุกคน"
L41_1.m_Talk_THA = L42_1
L42_1 = "Thật hân hạnh khi được gặp gỡ tất cả mọi người."
L41_1.m_Talk_VTN = L42_1
L42_1 = "大家好。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Es ist mir eine Freude, euch alle kennenzulernen."
L41_1.m_Talk_DEU = L42_1
L42_1 = "C'est un plaisir de faire votre connaissance."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
