L43_1 = "그리고 이쪽은 제 제자인 이윤정 조교에요."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "こちらは、私の弟子で助手をしてもらっている、ワタナベ・ユコです。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "This is my assistant, Lee Yoonjung."
L42_1.m_Talk_ENG = L43_1
L43_1 = "然後這一位是我的學生，李芸京助教。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "นี่ผู้ช่วยฉันเอง ลี ยุนจอง"
L42_1.m_Talk_THA = L43_1
L43_1 = "Đây là trợ lý của tôi, Lee Yoonjung."
L42_1.m_Talk_VTN = L43_1
L43_1 = "这一位是我的学生，李芸京助教。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Das ist meine Assistentin, Lee Yoonjung."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Voici mon assistante, Lee Yoonjung."
L42_1.m_Talk_FRA = L43_1
