L47_1.m_Pos = "L"
L48_1 = "다크서클이 턱까지 내려와 있는데."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "目の下のクマがアゴまで伸びてるよ？"
L47_1.m_Talk_JPN = L48_1
L48_1 = "You look like you haven't slept for days."
L47_1.m_Talk_ENG = L48_1
L48_1 = "妳的黑眼圈都快從眼睛蔓延到下巴了。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ทำไมดูเหมือนไม่ได้นอนติดกันหลายวันเลยล่ะ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Nhìn cậu như thể đã chưa ngủ nhiều ngày rồi vậy."
L47_1.m_Talk_VTN = L48_1
L48_1 = "你的黑眼圈都快从眼睛蔓延到下巴了。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Du siehst aus, als hättest du seit Tagen nicht geschlafen."
L47_1.m_Talk_DEU = L48_1
L48_1 = "On dirait que vous n'avez pas dormi depuis des jours."
L47_1.m_Talk_FRA = L48_1
