L1_1.m_fTalkTime = 0.03
L2_1 = "教授の代わりに……報告書をまとめてるから……"
L1_1.m_Talk_JPN = L2_1
L2_1 = "I've been... Writing reports on behalf of Dr. Olivie..."
L1_1.m_Talk_ENG = L2_1
