L2_1.m_Crash = 10
L3_1 = "지금 일주일째...... 밤을 새고 있어서......"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "今日まで一週間くらい……徹夜してて……"
L2_1.m_Talk_JPN = L3_1
L3_1 = "It's been a week... since I've had any sleep..."
L2_1.m_Talk_ENG = L3_1
L3_1 = "已經……熬了一個禮拜的夜了……"
L2_1.m_Talk_TWN = L3_1
L3_1 = "น่าจะอาทิตย์นึงได้แล้วมั้ง... ที่ฉันยังไม่ได้นอนเลย..."
L2_1.m_Talk_THA = L3_1
L3_1 = "Tôi chưa ngủ... cũng được một tuần rồi..."
L2_1.m_Talk_VTN = L3_1
L3_1 = "已经……熬了一个礼拜的夜了……"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Ich habe eine Woche lang … kaum ein Auge zugetan …"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Ça va faire une semaine... que je n'ai pas dormi..."
