L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "R"
L4_1 = "조교야, 방금 무슨 말 했니?"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "助手、いまなんて？"
L3_1.m_Talk_JPN = L4_1
L4_1 = "What was that? Did you say something, my dear?"
L3_1.m_Talk_ENG = L4_1
L4_1 = "助教，妳剛剛說什麼？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "อะไรน่ะ? เมื่อกี้เธอพูดอะไรรึเปล่าจ๊ะ ที่รัก?"
L3_1.m_Talk_THA = L4_1
L4_1 = "Gì vậy? Em nói gì thế, em yêu của ta?"
L3_1.m_Talk_VTN = L4_1
L4_1 = "助教啊，你刚刚有说什么话吗？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Wie bitte? Hast du etwas gesagt, meine Liebe?"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Plaît-il ? Avez-vous dit quelque chose, ma chère ?"
L3_1.m_Talk_FRA = L4_1
