L45_1 = "入社同期で私の初ダイブも一緒だなんて……"
L44_1.m_Talk_JPN = L45_1
L45_1 = "I'm so happy my first dive was with my new friend..."
L44_1.m_Talk_ENG = L45_1
L45_1 = "連進公司的第一次躍入都是和米娜一起。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ดีใจจังที่ได้ไดฟ์ครั้งแรกกับเพื่อนใหม่..."
L44_1.m_Talk_THA = L45_1
L45_1 = "Tôi rất vui vì lần lặn đầu tiên của mình lại là lần lặn chung với người bạn mới..."
L44_1.m_Talk_VTN = L45_1
L45_1 = "和米娜一起进行了第一次跃入唉，"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Ich bin froh, dass ich meinen ersten Tauchgang mit meiner neuen Freundin habe!"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Je suis vraiment contente que ma première plongée ait été avec ma nouvelle amie..."
L44_1.m_Talk_FRA = L45_1
