L47_1 = "그러고 보니 너도 다이브는 처음이라고 했지?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "そういえば、あなたもダイブは初めてだとか？"
