L47_1 = "這麼說來，妳也是第一次躍入囉？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ว่าแต่ เมื่อกี้เธอบอกว่า นี่ก็เป็นการไดฟ์ครั้งแรกของเธอเหมือนกันงั้นเหรอ?"
