L2_1 = "......뭐, 다들 사정이 있어서 흘러들어 온 거긴 하지."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "……まあ、ここに流れ着いてる人はみんなワケありだよね。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "I guess everyone has a complicated story behind how they got here."
L1_1.m_Talk_ENG = L2_1
L2_1 = "嗯，大家都是有自己的原因才會在這裡的嘛。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ฉันว่าทุกคนก็คงมีเรื่องซับซ้อนด้วยกันทั้งนั้นแหละนะ ก่อนจะมาถึงจุดนี้"
L1_1.m_Talk_THA = L2_1
L2_1 = "Tôi đoán mỗi người đều có một câu chuyện phức tạp đằng sau nguyên nhân họ đến đây."
L1_1.m_Talk_VTN = L2_1
L2_1 = "......大家都是因为各自的原因，才来到这个小队。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Ich glaube, jeder, der hierher gekommen ist, hat eine komplizierte Geschichte."
L1_1.m_Talk_DEU = L2_1
L2_1 = "J'imagine que tous ceux qui se retrouvent ici sont arrivés dans des circonstances compliquées."
