L7_1 = "當然啦！"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ทำไมจะไม่ดีใจล่ะ!"
L6_1.m_Talk_THA = L7_1
L7_1 = "Sao tôi lại không thể chứ!"
L6_1.m_Talk_VTN = L7_1
L7_1 = "当然啦！"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Warum auch nicht?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "J'ai toutes les raisons de l'être !"
L6_1.m_Talk_FRA = L7_1
