L8_1 = "EP1_ACT2_STAGE1_START@257#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 257
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 18
L7_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "SEOYOON_ALT_NULL_NULL"
L7_1.m_Pos = "L"
L8_1 = "우리 같은 언더 소대에게 다이브 작전이란 건, 아이돌의 메이저 데뷔 무대 같은 거라고!"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "私たちみたいなアンダーグラウンドの小隊にとって、ダイブ作戦はアイドルのメジャーデビューみたいなものだから！"
L7_1.m_Talk_JPN = L8_1
L8_1 = "For a second class squad like us, a dive mission is like the debut show for a rock star!"
L7_1.m_Talk_ENG = L8_1
L8_1 = "對我們這種地下小隊來說，躍入作戰就相當於偶像的出道舞臺啊！"
L7_1.m_Talk_TWN = L8_1
L8_1 = "สำหรับหน่วยที่ไม่มีใบอนุญาตอย่างเรา ภารกิจไดฟ์ก็เหมือนโชว์แรกของร็อกสตาร์นั่นแหละ!"
L7_1.m_Talk_THA = L8_1
L8_1 = "Đối với một Tiểu đội không có giấy phép như bọn tôi, một nhiệm vụ lặn cũng giống như buổi ra mắt của một ngôi sao nhạc rock vậy đó!"
L7_1.m_Talk_VTN = L8_1
L8_1 = "对我们这种地下小队来说，跃入作战就相当于偶像出道的舞台啊！"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Für einen zweitklassigen Trupp wie uns ist eine Tauchmission wie der erste Auftritt eines Rockstars!"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Pour une escouade de seconde division comme nous, une mission de plongée c'est comme le tout premier concert d'une rock star !"
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "EP1_ACT2_STAGE1_START@258#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 258
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 18
L8_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "SEOYOON_ALT_NULL_NULL"
L8_1.m_Pos = "L"
L9_1 = "열심히 하겠습니다~! 같은 느낌?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "これから精一杯頑張りま～す！みたいな感じ？"
L8_1.m_Talk_JPN = L9_1
L9_1 = "I just want to do the best I can. You know what I mean?"
L8_1.m_Talk_ENG = L9_1
L9_1 = "我會加油的～就像這種感覺吧？"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ฉันก็แค่อยากจะทำออกมาให้ดีที่สุดน่ะ เข้าใจฉันใช่มั้ย?"
L8_1.m_Talk_THA = L9_1
L9_1 = "Tôi chỉ muốn làm hết sức mình thôi. Cậu hiểu ý tôi chứ?"
L8_1.m_Talk_VTN = L9_1
L9_1 = "所以得对自己说“要加把劲啦！”。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Ich will nur mein Bestes geben. Verstehst du, was ich meine?"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Je veux vraiment faire de mon mieux. Tu comprends ?"
L8_1.m_Talk_FRA = L9_1
