L11_1 = "......표정이 별로 안 좋아 보이는데."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "……顔色が冴えないけど。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "You don't look happy at all..."
L10_1.m_Talk_ENG = L11_1
L11_1 = "……妳的臉色看起來不太好呢。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ทำไมเธอดูไม่มีความสุขเลยล่ะ..."
L10_1.m_Talk_THA = L11_1
L11_1 = "Trông cậu chẳng vui chút nào..."
L10_1.m_Talk_VTN = L11_1
L11_1 = "……你的表情看起来不太好啊。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Du wirkst überhaupt nicht glücklich …"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Tu n'as pas l'air heureuse du tout..."
L10_1.m_Talk_FRA = L11_1
