L17_1 = "EP1_ACT2_STAGE1_START@266#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 266
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 18
L16_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "LENA_COFFIN_NULL_NULL"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "C"
L17_1 = "본 함은 현재, 무사히 다이브를 마치고 목표 지점에 도착했습니다."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "当艦は現在、無事にダイブを完了し、目標地点に到着しました。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "This ship has completed the dive and we have arrived at our destination."
L16_1.m_Talk_ENG = L17_1
L17_1 = "目前本艦已順利完成躍入，抵達目的地。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ยานลำนี้ไดฟ์เสร็จเรียบร้อย และเดินทางถึงที่หมายแล้ว"
L16_1.m_Talk_THA = L17_1
L17_1 = "Con tàu này đã hoàn thành chuyến lặn và chúng ta đã đến đích."
L16_1.m_Talk_VTN = L17_1
L17_1 = "目前本舰已顺利完成跃入，抵达目的地。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Das Schiff hat den Tauchgang beendet, und wir haben unser Ziel erreicht."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Le vaisseau a terminé la plongée et nous sommes arrivés à destination."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "EP1_ACT2_STAGE1_START@267#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 267
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 18
L17_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "LENA_COFFIN_NULL_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "C"
L18_1 = "또한 본 함의 출현을 감지한 침식체들이 주변으로 집결하고 있는 중입니다."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "また、当艦の出現に気づいた侵食体が周辺に集まってきています。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Corrupted objects have detected our ship, and are now assembling in our vicinity."
L17_1.m_Talk_ENG = L18_1
L18_1 = "另外，已偵測到侵蝕體正在向艦船周圍聚集。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "วัตถุคอร์รัปต์พบยานของเราแล้ว และกำลังรวมตัวอยู่ในบริเวณใกล้กับเรา"
L17_1.m_Talk_THA = L18_1
L18_1 = "Các Đối Tượng Bị Ăn Mòn đã phát hiện tàu của chúng ta, và hiện đang lắp ráp trong vùng lân cận."
L17_1.m_Talk_VTN = L18_1
L18_1 = "另外，已侦测到侵蚀体正在向舰船周围聚集。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Counterside-Objekte haben unser Schiff entdeckt und sammeln sich nun in unserer Nähe."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Des objets corrompus ont repéré notre vaisseau et se rassemblent aux alentours."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "EP1_ACT2_STAGE1_START@268#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 268
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 18
L18_1.m_CutScenStrID = "EP1_ACT2_STAGE1_START"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "LENA_COFFIN_NULL_NULL"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "C"
L19_1 = "각 소대는 즉시 출격하여 주변의 침식체들을 격파 후, 강하지점의 안전을 확보해 주시기 바랍니다."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "各小隊はただちに出撃、周辺の侵食体を撃破した後、降下地点の安全を確保してください。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Each squad must immediately head out and destroy the Corrupted Objects, then secure our descent point."
L18_1.m_Talk_ENG = L19_1
L19_1 = "請各小隊立刻出擊，消滅艦船周圍的侵蝕體，以確保艦船的降落地點。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ทุกหน่วยจะต้องออกไปกำจัดวัตถุคอร์รัปต์โดยด่วน แล้วคุ้มกันจุดลงจอดของพวกเรา"
L18_1.m_Talk_THA = L19_1
L19_1 = "Mỗi Tiểu đội phải lập tức ra ngoài và tiêu diệt các Đối Tượng Bị Ăn Mòn, sau đó bảo vệ điểm hạ cánh của chúng ta."
L18_1.m_Talk_VTN = L19_1
L19_1 = "请各小队立即出击，消灭舰船周边的侵蚀体，以确保舰船安全降落。"
L18_1.m_Talk_SCN = L19_1
